def money(x):
    try:
        return '{:,.2f}'.format(float(x))
    except Exception:
        return str(x)
def to_list(v):
    if isinstance(v, str):
        s = v.strip()
        try:
            v = json.loads(s)
        except Exception:
            try:
                v = json.loads(s.replace("'", '"').replace('True', 'true').replace('False', 'false').replace('None', 'null'))
            except Exception:
                v = None
    if isinstance(v, dict):
        return [v]
    if isinstance(v, list):
        return [x for x in v if isinstance(x, dict)]
    return []
def get_products():
